def run(self):
    base = "https://searchfox.org/{source}/source/{path}"

    if ":" in self.target:
        source, path = self.target.split(":", 1)
    else:
        source = "comm-central"
        path = self.target

    if path.startswith("comm/"):
        path = path[5:]

    url = base.format(source=source, path=path)

    if self.has_explicit_title:
        title = self.title
    else:
        title = path
